#include "actions.h"
#include "shopping.h"
#include <cstdio>
#include <memory>
#include <stdexcept>
using namespace tactics;
static void check(bool b,const char*why){if(!b){std::printf("CASH_PRODUCER_FAIL %s\n",why);std::fflush(stdout);throw std::runtime_error(why);}}
static void burn(unsigned f){volatile unsigned x=1;while(bc::fuel_remaining()>f)x=x*1664525+1013904223;}
int main(){Geometry geo;Memory memory;ShoppingState shop;std::unique_ptr<World>world;bool done=false;while(true){if(bc::is_draft()){bc::draft::pick(bc::champion_draft::cassi_and_issac);bc::end_turn();continue;}const int id=identity(bc::self());if(done||id==1||id==3){bc::end_turn();continue;}geo.initialize();if(!geo.initialized){bc::end_turn();continue;}Pos target=id==0?Pos{5,5}:Pos{26,5};if(!geo.goal_field(target,0)){bc::end_turn();continue;}if(world&&bc::fuel_remaining()>80000)if(auto hint=shopping_gem_route_hint(*world,shop))geo.goal_field(*hint,0);if(!world)world=std::make_unique<World>(geo,memory);world->refresh();auto&w=*world;if(w.self.pos!=target){if(auto next=w.toward(target)){Action a;a.kind=Kind::Move;a.at=*next;check(execute(w,a).outcome==Outcome::Applied,"physical staging move");}bc::end_turn();continue;}check(w.gold==0&&w.self.type==3,"actual empty-wallet Cassi");burn(65000);const int start=bc::fuel_remaining();plan_upgrade_return(w,memory,shop);const int end=bc::fuel_remaining();std::printf("CASH_PRODUCER_QUOTE %d %d %d %d %d\n",id,w.round,start,end,memory.cash_investment_group);check(w.round==int(bc::round_number()),"same-owner quote");check(end>=40000&&start-end<=18000,"bounded65k producer");if(memory.cash_investment_group>=0){const auto&c=shop.cash;check(c.group==memory.cash_investment_group&&c.item==28&&c.count==1&&c.expected_gold==35&&c.gem_mission.group>=0,"exact finite cash shard gem receipt");check(w.geo.groups[c.group].gems==0&&w.geo.groups[c.gem_mission.group].gems==22,"actual cash and Wolf rewards");check(w.gold==0&&w.me.item_count()[shop_item(28)]==0&&shop.investment_item<0,"quote never installs projected wallet or inventory");std::printf("CASH_PRODUCER_PASS %d %d %d %d %d\n",id,w.round,start,end,c.gem_mission.group);done=true;}check(w.round<50,"producer activates before bounded advisory deadline");bc::end_turn();}}
